/**
 * US-22 — parse_staff_command.
 *
 * El personal de la farmacia marca el avance del despacho desde Telegram, sin
 * app del conductor (fuera del alcance firmado). Autorización en dos capas,
 * igual que US-20:
 *   1. Secreto del webhook (X-Telegram-Bot-Api-Secret-Token == $env.TELEGRAM_WEBHOOK_SECRET).
 *   2. El chat debe estar en $env.TELEGRAM_STAFF_CHAT_IDS; si esa lista está
 *      vacía se usa $env.TELEGRAM_PHARMACIST_CHAT_IDS. Cualquier otro chat se
 *      descarta en silencio.
 *
 * Comandos (sin distinguir mayúsculas, "/" y "#" opcionales):
 *   en ruta FAR-XXXX   (también: ruta, despachar)  -> command "ruta"
 *   entregado FAR-XXXX (también: entregar)          -> command "entregado"
 *
 * Salida: UN ítem { chat_id, command, codigo_far, text } o [].
 */
function isAuthorized(headers, secret) {
  if (!headers || typeof headers !== 'object') return false;
  if (typeof secret !== 'string' || !secret) return false;
  const key = Object.keys(headers).find(
    (name) => typeof name === 'string' && name.toLowerCase() === 'x-telegram-bot-api-secret-token'
  );
  if (!key) return false;
  const value = headers[key];
  return typeof value === 'string' && value === secret;
}

function parseIdList(list) {
  const raw = typeof list === 'string' ? list : '';
  return raw.split(',').map((s) => s.trim()).filter((s) => s.length > 0);
}

/** El chat está autorizado si figura en la lista de personal (o, sin ella, en la de farmacéuticos). */
function isStaff(chatId, staffList, pharmacistList) {
  if (chatId === null || chatId === undefined) return false;
  const staff = parseIdList(staffList);
  const ids = staff.length ? staff : parseIdList(pharmacistList);
  return ids.length > 0 && ids.indexOf(String(chatId)) !== -1;
}

/** "en ruta FAR-0001" -> { command: 'ruta', codigo_far: '#FAR-0001' }; null si no es comando. */
function parseStaffCommand(text) {
  if (typeof text !== 'string') return null;
  const m = /^\s*\/?\s*(en\s+ruta|ruta|despachar|entregado|entregar)\s+#?\s*FAR-?(\d{4})\b/i.exec(text);
  if (!m) return null;
  const verbo = m[1].toLowerCase().replace(/\s+/g, ' ');
  const command = verbo === 'entregado' || verbo === 'entregar' ? 'entregado' : 'ruta';
  return { command: command, codigo_far: '#FAR-' + m[2] };
}

function parseTelegramUpdate(update, headers, secret, staffList, pharmacistList) {
  if (!isAuthorized(headers, secret)) return [];
  if (!update || typeof update !== 'object') return [];
  const message = update.message;
  if (!message || typeof message !== 'object') return [];
  const chat =
    message.chat && (typeof message.chat.id === 'string' || typeof message.chat.id === 'number')
      ? String(message.chat.id)
      : '';
  if (!chat) return [];
  if (!isStaff(chat, staffList, pharmacistList)) return [];
  const text = typeof message.text === 'string' ? message.text.trim() : '';
  const parsed = parseStaffCommand(text);
  if (!parsed) return [];
  return [{ json: { chat_id: chat, command: parsed.command, codigo_far: parsed.codigo_far, text: text } }];
}

// --- ensamblaje n8n (protegido para que el arnés de pruebas cargue las funciones) ---
if (typeof $input !== 'undefined') {
  try {
    const items = $input.all();
    for (let i = 0; i < items.length; i++) {
      const json = items[i] && items[i].json ? items[i].json : items[i];
      const headers = json && json.headers && typeof json.headers === 'object' ? json.headers : {};
      const update = json && json.body && typeof json.body === 'object' ? json.body : json;
      const out = parseTelegramUpdate(
        update,
        headers,
        $env.TELEGRAM_WEBHOOK_SECRET,
        $env.TELEGRAM_STAFF_CHAT_IDS,
        $env.TELEGRAM_PHARMACIST_CHAT_IDS
      );
      if (out.length) return out;
    }
  } catch (err) {
    return [];
  }
  return [];
}

/**
 * US-22 — evaluate_dispatch.
 *
 * Aplica la transición logística de UN comando del personal:
 *   ruta      + EN_PREPARACION -> EN_RUTA    (sin efecto en stock)
 *   entregado + EN_RUTA        -> ENTREGADO  (descuenta stock_real y libera
 *                                             stock_reservado UNA sola vez)
 * Cualquier otra combinación es INVALID y no escribe nada: el estado de origen
 * es la guarda de idempotencia, de modo que repetir "entregado" nunca descuenta
 * dos veces. Cada transición válida deja su fila en la bitácora con
 * estado_anterior, estado_nuevo y actor (personal:<chat_id>) y avisa al vecino.
 */
const ESTADO_PREPARACION = 'EN_PREPARACION';
const ESTADO_RUTA = 'EN_RUTA';
const ESTADO_ENTREGADO = 'ENTREGADO';
const ACCION_RUTA = 'DESPACHO_EN_RUTA';
const ACCION_ENTREGA = 'PEDIDO_ENTREGADO';

function normalize(s) {
  return String(s === null || s === undefined ? '' : s)
    .toLowerCase()
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

function rowJson(item) {
  return item && item.json ? item.json : item;
}

function codigoKey(value) {
  return String(value === null || value === undefined ? '' : value).toUpperCase().replace(/^#/, '').trim();
}

function findOrderByCode(codigo, orderItems) {
  const key = codigoKey(codigo);
  if (!key) return null;
  const rows = (orderItems || []).map(rowJson).filter((r) => r && typeof r === 'object');
  for (let i = 0; i < rows.length; i++) {
    if (codigoKey(rows[i].codigo_far) === key) return rows[i];
  }
  return null;
}

function findInventoryFor(medicamentoId, inventoryItems) {
  const key = normalize(medicamentoId);
  if (!key) return null;
  const rows = (inventoryItems || []).map(rowJson).filter((r) => r && typeof r === 'object');
  for (let i = 0; i < rows.length; i++) {
    if (normalize(rows[i].medicamento_id) === key) return rows[i];
  }
  return null;
}

/** Decisión pura sobre el estado del pedido. Nunca lanza excepciones. */
function decideDispatch(order, command, codigoRaw) {
  const codigo = order
    ? '#' + codigoKey(order.codigo_far)
    : (codigoRaw ? '#' + codigoKey(codigoRaw) : '#FAR-XXXX');
  const estado = order && order.estado ? String(order.estado) : '';
  const base = {
    decisionKey: 'INVALID',
    estado_anterior: '',
    estado_nuevo: '',
    staff_message: '',
    customer_message: ''
  };
  if (!order) {
    base.staff_message = 'No encontré el pedido ' + codigo + '.';
    return base;
  }
  if (command === 'ruta') {
    if (estado === ESTADO_PREPARACION) {
      base.decisionKey = 'EN_RUTA';
      base.estado_anterior = ESTADO_PREPARACION;
      base.estado_nuevo = ESTADO_RUTA;
      base.staff_message = 'Listo: ' + codigo + ' pasa a ' + ESTADO_RUTA + '. Se avisó al vecino.';
      base.customer_message = 'Su pedido ' + codigo + ' va en camino. El conductor de la farmacia lo entregará en la dirección registrada.';
      return base;
    }
    base.staff_message = estado === ESTADO_RUTA
      ? codigo + ' ya estaba ' + ESTADO_RUTA + '. No se aplicó ningún cambio.'
      : codigo + ' no está en ' + ESTADO_PREPARACION + ' (estado actual: ' + (estado || 'desconocido') + '). No se aplicó ningún cambio.';
    return base;
  }
  if (command === 'entregado') {
    if (estado === ESTADO_RUTA) {
      base.decisionKey = 'ENTREGADO';
      base.estado_anterior = ESTADO_RUTA;
      base.estado_nuevo = ESTADO_ENTREGADO;
      base.staff_message = 'Listo: ' + codigo + ' quedó ' + ESTADO_ENTREGADO + ' y se descontó el stock.';
      base.customer_message = 'Su pedido ' + codigo + ' fue entregado. Gracias por preferir la Farmacia Comunitaria de Peñalolén.';
      return base;
    }
    base.staff_message = estado === ESTADO_ENTREGADO
      ? codigo + ' ya estaba ' + ESTADO_ENTREGADO + '. No se aplicó ningún cambio.'
      : codigo + ' no está ' + ESTADO_RUTA + ' (estado actual: ' + (estado || 'desconocido') + '). Primero márquelo "en ruta".';
    return base;
  }
  base.staff_message = 'Comando no reconocido. Use "en ruta FAR-XXXX" o "entregado FAR-XXXX".';
  return base;
}

/**
 * Al entregar, el pedido sale físicamente de bodega: stock_real y
 * stock_reservado bajan en la cantidad del pedido, ambos con piso 0.
 * Devuelve null si falta la fila de inventario (se avisa en vez de escribir).
 */
function buildInventoryUpdate(order, invRow, nowIso) {
  if (!order || !invRow) return null;
  const cantidad = Math.abs(Number(order.cantidad) || 0);
  const real = Number(invRow.stock_real);
  const reserved = Number(invRow.stock_reservado);
  return {
    medicamento_id: order.medicamento_id,
    stock_real: Math.max(0, (isNaN(real) ? 0 : real) - cantidad),
    stock_reservado: Math.max(0, (isNaN(reserved) ? 0 : reserved) - cantidad),
    ultima_actualizacion: nowIso || new Date().toISOString()
  };
}

function buildBitacoraRow(order, decision, chatId, nowIso) {
  const entrega = decision.decisionKey === 'ENTREGADO';
  return {
    timestamp: nowIso || new Date().toISOString(),
    accion: entrega ? ACCION_ENTREGA : ACCION_RUTA,
    codigo_far: codigoKey(order.codigo_far),
    medicamento_id: order.medicamento_id,
    delta_reservado: entrega ? -Math.abs(Number(order.cantidad) || 0) : 0,
    detalle: entrega
      ? 'Entrega confirmada por el personal vía Telegram; se descuenta stock_real y stock_reservado'
      : 'Despacho iniciado por el personal vía Telegram',
    estado_anterior: decision.estado_anterior,
    estado_nuevo: decision.estado_nuevo,
    actor: 'personal:' + chatId
  };
}

function evaluateDispatch(parsed, orderItems, inventoryItems, nowIso) {
  if (!parsed || !parsed.chat_id || !parsed.command || !parsed.codigo_far) return null;
  const now = nowIso || new Date().toISOString();
  const order = findOrderByCode(parsed.codigo_far, orderItems);
  const decision = decideDispatch(order, parsed.command, parsed.codigo_far);
  const payload = {
    chat_id: String(parsed.chat_id),
    codigo_far: codigoKey(parsed.codigo_far),
    decision: decision.decisionKey,
    estado_anterior: decision.estado_anterior,
    estado_nuevo: decision.estado_nuevo,
    estado_ruta: decision.decisionKey === 'INVALID' ? '' : decision.estado_nuevo,
    fecha_marcado: now,
    update_stock: 'NO',
    inventory_update: null,
    bitacora_row: null,
    telefono: order && order.telefono !== null && order.telefono !== undefined ? String(order.telefono) : '',
    message_staff: decision.staff_message,
    message_customer: decision.customer_message || ''
  };
  if (decision.decisionKey === 'ENTREGADO' && order) {
    const inventoryUpdate = buildInventoryUpdate(order, findInventoryFor(order.medicamento_id, inventoryItems), now);
    if (inventoryUpdate) {
      payload.update_stock = 'SI';
      payload.inventory_update = inventoryUpdate;
    } else {
      payload.message_staff += ' Advertencia: no se encontró la fila de inventario; revisar manualmente.';
    }
  }
  if (decision.decisionKey !== 'INVALID') {
    payload.bitacora_row = buildBitacoraRow(order, decision, parsed.chat_id, now);
  }
  return payload;
}

// --- ensamblaje n8n (protegido para que el arnés de pruebas cargue las funciones) ---
if (typeof $ !== 'undefined' && typeof $input !== 'undefined') {
  let parsed = null;
  try {
    parsed = $('parse_staff_command').first().json;
  } catch (err) {
    parsed = null;
  }
  if (!parsed) return [];
  const payload = evaluateDispatch(parsed, $('read_ordenes').all(), $('read_inventario').all(), new Date().toISOString());
  if (!payload) return [];
  return [{ json: payload }];
}
